-- 07_LOOKUP_SYNC.sql (v2 정정 2026-08-12) — PK = (LOOKUP_TYPE, SEGMENT1..SEGMENT5) 6컬럼 실측
--   구판 결함: ON 5키(SEG1~4) → 클라우드에 같은 SEG1~4·SEGMENT5 상이 구행 공존 시
--   UPDATE SET SEGMENT5 가 기존 행과 PK 충돌(ORA-00001). 정정 = ①구행 선삭제(같은 논리키의
--   SEG5 변형 — PK 충돌 원인 행만 표적) ②PK 6키 UPSERT(UPDATE 는 속성만).

DELETE FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
 WHERE LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE' AND NVL(SEGMENT1,'~') = NVL('ADMIN','~') AND NVL(SEGMENT2,'~') = NVL('DMF0082','~') AND NVL(SEGMENT3,'~') = NVL('40','~') AND NVL(SEGMENT4,'~') = NVL('LOC','~')
   AND NVL(SEGMENT5,'~') <> NVL('-','~');
MERGE INTO SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL T
USING (SELECT 'GET_ADMIN_GROUP_MEASURE' AS LOOKUP_TYPE, 'ADMIN' AS SEGMENT1, 'DMF0082' AS SEGMENT2, '40' AS SEGMENT3, 'LOC' AS SEGMENT4, '-' AS SEGMENT5 FROM DUAL) S ON (NVL(T.LOOKUP_TYPE,'~') = NVL(S.LOOKUP_TYPE,'~') AND NVL(T.SEGMENT1,'~') = NVL(S.SEGMENT1,'~') AND NVL(T.SEGMENT2,'~') = NVL(S.SEGMENT2,'~') AND NVL(T.SEGMENT3,'~') = NVL(S.SEGMENT3,'~') AND NVL(T.SEGMENT4,'~') = NVL(S.SEGMENT4,'~') AND NVL(T.SEGMENT5,'~') = NVL(S.SEGMENT5,'~'))
WHEN MATCHED THEN UPDATE SET ATTRIBUTE1 = NULL, ATTRIBUTE2 = NULL, ATTRIBUTE3 = NULL, ATTRIBUTE4 = NULL, DISPLAY_SEQ = '7', VALID_YN = 'Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (LOOKUP_TYPE, SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, DISPLAY_SEQ, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('GET_ADMIN_GROUP_MEASURE', 'ADMIN', 'DMF0082', '40', 'LOC', '-', NULL, NULL, NULL, NULL, '7', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
