   AND NVL(SEGMENT5,'~') <> NVL('-','~');
MERGE INTO SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL T
USING (SELECT 'GET_ADMIN_GROUP_MEASURE' AS LOOKUP_TYPE, 'SCM PI Admin' AS SEGMENT1, 'DMF0082' AS SEGMENT2, '40' AS SEGMENT3, 'LOC' AS SEGMENT4, '-' AS SEGMENT5 FROM DUAL) S ON (NVL(T.LOOKUP_TYPE,'~') = NVL(S.LOOKUP_TYPE,'~') AND NVL(T.SEGMENT1,'~') = NVL(S.SEGMENT1,'~') AND NVL(T.SEGMENT2,'~') = NVL(S.SEGMENT2,'~') AND NVL(T.SEGMENT3,'~') = NVL(S.SEGMENT3,'~') AND NVL(T.SEGMENT4,'~') = NVL(S.SEGMENT4,'~') AND NVL(T.SEGMENT5,'~') = NVL(S.SEGMENT5,'~'))
WHEN MATCHED THEN UPDATE SET ATTRIBUTE1 = NULL, ATTRIBUTE2 = NULL, ATTRIBUTE3 = NULL, ATTRIBUTE4 = NULL, DISPLAY_SEQ = '7', VALID_YN = 'Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (LOOKUP_TYPE, SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, DISPLAY_SEQ, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('GET_ADMIN_GROUP_MEASURE', 'SCM PI Admin', 'DMF0082', '40', 'LOC', '-', NULL, NULL, NULL, NULL, '7', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
